export function getLocationFromCatalog(slug: string): Location | undefined {
  const lower = slug.toLowerCase();
  return LOCATIONS_CATALOG.find(
    (l) => l.slug.toLowerCase() === lower || l.name.toLowerCase() === lower
  );
}
